const PROCESSING_FEE = 5;

const BASE_PREMIUM = 100;

const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

export type ScenarioResult = { premium: number };

export type ScenarioOutcome = { results: ScenarioResult[] };

type Item = unknown;

type Scenario = { steps: { items: Item[] }[] };

const basePremiumOf = (item: Item): number => BASE_PREMIUM;

const withFirstInsuranceSurcharge = (amount: number): number =>
  amount * (1 + FIRST_INSURANCE_SURCHARGE_RATE);

const quotePremium = (items: Item[]): number => {
  const basePremium = items.reduce(
    (total, item) => total + basePremiumOf(item),
    0,
  );

  return withFirstInsuranceSurcharge(basePremium) + PROCESSING_FEE;
};

export const runScenario = (scenario: unknown): ScenarioOutcome => {
  const { steps } = scenario as Scenario;

  const results = steps.map((step) => ({ premium: quotePremium(step.items) }));

  return { results };
};

